var skins = [0, 1, 2, 3, 4, 9];

function action(mode, type, selection) {
    if (mode <= 0) {
        cm.dispose();
        return;
    }
    status++;
    if (status === 0) {
        cm.sendSimple("#e#r 发型/脸型测试工具 #k#n\r\n\r\n" +
            "当前发型: #b" + cm.getPlayer().getHair() + "#k\r\n" +
            "当前脸型: #b" + cm.getPlayer().getFace() + "#k\r\n" +
            "当前肤色: #b" + cm.getPlayer().getSkinColor() + "#k\r\n\r\n" +
            "#L0#更换发型（手动输入代码）#l\r\n" +
            "#L1#更换脸型（手动输入代码）#l\r\n" +
            "#L2#更换肤色#l");
    } else if (status === 1) {
        if (selection === 0) {
            beauty = 1;
            cm.sendGetText("请输入发型代码（例如：30000）：");
        } else if (selection === 1) {
            beauty = 2;
            cm.sendGetText("请输入脸型代码（例如：20000）：");
        } else if (selection === 2) {
            beauty = 3;
            cm.sendStyle("挑选一款肤色吧！", skins);
        }
    } else if (status === 2) {
        if (beauty === 1) {
            var inputHair = parseInt(cm.getText());
            if (isNaN(inputHair)) {
                cm.sendOk("#r输入无效！请输入纯数字的发型代码。#k");
                cm.dispose();
                return;
            }
            if (validHairIds.has(inputHair)) {
                cm.setHair(inputHair);
                cm.sendOk("#b发型更换成功！新发型代码：" + inputHair + "#k");
            } else {
                cm.sendOk("#r发型代码 " + inputHair + " 不存在于WZ文件中，无法更换！#k\r\n\r\n请确认代码是否正确后重试。");
            }
        } else if (beauty === 2) {
            var inputFace = parseInt(cm.getText());
            if (isNaN(inputFace)) {
                cm.sendOk("#r输入无效！请输入纯数字的脸型代码。#k");
                cm.dispose();
                return;
            }
            if (validFaceIds.has(inputFace)) {
                cm.setFace(inputFace);
                cm.sendOk("#b脸型更换成功！新脸型代码：" + inputFace + "#k");
            } else {
                cm.sendOk("#r脸型代码 " + inputFace + " 不存在于WZ文件中，无法更换！#k\r\n\r\n请确认代码是否正确后重试。");
            }
        } else if (beauty === 3) {
            cm.setSkin(skins[selection]);
            cm.sendOk("#b肤色更换成功！#k");
        }
        cm.dispose();
    }
}
